package org.pocketlore.app;
import android.app.*;import android.content.*;import android.os.*;import android.widget.*;import android.view.accessibility.AccessibilityNodeInfo;import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;import org.json.*;
/** Supplemental actual source-button check; no model generation and no generated-link credit. */
public final class BroadInstrumentation extends Instrumentation {
 static Object reflect(Object o,String n){try{java.lang.reflect.Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}catch(Exception e){throw new RuntimeException(e);}}
 String mode; MainActivity a;File root;JSONObject report=new JSONObject();JSONArray dialogs=new JSONArray();
 Object field(Object o,String n){return reflect(o,n);}void check(boolean b,String m){if(!b)throw new AssertionError(m);}
 void await(java.util.function.BooleanSupplier f)throws Exception{long end=System.nanoTime()+60_000_000_000L;while(!f.getAsBoolean()&&System.nanoTime()<end)Thread.sleep(20);check(f.getAsBoolean(),"UI timeout");}
 void ready()throws Exception{await(()->{boolean[] b={false};runOnMainSync(()->b[0]=!(Boolean)field(a,"searching")&&!(Boolean)field(a,"importing")&&a.resourceIdle());return b[0];});}
 void click(Object o,String n){runOnMainSync(()->{Button b=(Button)field(o,n);check(b.isEnabled(),"Disabled "+n);b.performClick();});}
 String visible(AccessibilityNodeInfo n){if(n==null)return "";String s=n.getText()==null?"":n.getText()+"\n";for(int i=0;i<n.getChildCount();i++)s+=visible(n.getChild(i));return s;}
 boolean tap(AccessibilityNodeInfo n,String label){if(n==null)return false;if(n.getText()!=null&&n.getText().toString().equalsIgnoreCase(label)){while(n!=null){if(n.isClickable())return n.performAction(AccessibilityNodeInfo.ACTION_CLICK);n=n.getParent();}return false;}for(int i=0;i<n.getChildCount();i++)if(tap(n.getChild(i),label))return true;return false;}
 void tap(String s)throws Exception{await(()->visible(getUiAutomation().getRootInActiveWindow()).toLowerCase(Locale.ROOT).contains(s.toLowerCase(Locale.ROOT)));check(tap(getUiAutomation().getRootInActiveWindow(),s),"Cannot click "+s);getUiAutomation().waitForIdle(100,3000);}
 void search(String question,boolean disabled)throws Exception{
  runOnMainSync(()->((EditText)field(a,"question")).setText(question));click(a,"search");ready();check(!a.latestAnswer().invokedModel,"Unexpected model invocation");ResearchEngine.Result r=(ResearchEngine.Result)field(a,"latestEvidence");Set<String> editions=new HashSet<>();
  for(int i=0;i<r.hits.size();i++){ResearchEngine.Passage p=r.hits.get(i).passage;editions.add(p.id.split("_")[0]);if(disabled)check(!p.id.contains("c69f31299553f4a1168eaa0400129fd5e41f21b4354248a0e2b97a87546ff274"),"Disabled source leaked");final int j=i;runOnMainSync(()->((LinearLayout)field(a,"sourceList")).getChildAt(j).performClick());await(()->visible(getUiAutomation().getRootInActiveWindow()).contains(p.text));String text=visible(getUiAutomation().getRootInActiveWindow());check(text.contains(p.id)&&text.contains(p.url)&&text.contains(p.sourceDate)&&text.contains(p.license)&&text.contains(p.collectionProvenance),"Dialog provenance mismatch");String name=(disabled?"disabled-":"combined-")+i;android.graphics.Bitmap image=getUiAutomation().takeScreenshot();check(image!=null,"No screenshot");try(FileOutputStream out=new FileOutputStream(new File(root,name+".png"))){image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}image.recycle();dialogs.put(new JSONObject().put("file",name+".png").put("citation",p.id).put("disabled_science",disabled).put("visible",text).put("route",a.latestAnswer().kind.name()).put("invoked",false));tap("Close");}
  check(editions.size()==(disabled?1:2),"Unexpected source edition coverage");
 }
 void capture(String name)throws Exception{android.graphics.Bitmap image=getUiAutomation().takeScreenshot();check(image!=null,"Screenshot unavailable");try(FileOutputStream out=new FileOutputStream(new File(root,name+".png"))){image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}image.recycle();}
 JSONObject memory()throws Exception{android.os.Debug.MemoryInfo m=new android.os.Debug.MemoryInfo();android.os.Debug.getMemoryInfo(m);JSONObject r=new JSONObject().put("pss_kib",m.getTotalPss()).put("java_used",Runtime.getRuntime().totalMemory()-Runtime.getRuntime().freeMemory());for(String s:Files.readAllLines(Paths.get("/proc/self/status")))if(s.startsWith("VmRSS:")||s.startsWith("VmSwap:")){String[] v=s.trim().split("\\s+");r.put(v[0].replace(":",""),Long.parseLong(v[1]));}return r;}
 void importPack(String name,boolean cancel)throws Exception{
  IntentFilter f=new IntentFilter(Intent.ACTION_OPEN_DOCUMENT);f.addCategory(Intent.CATEGORY_OPENABLE);f.addDataType("*/*");ActivityMonitor monitor=addMonitor(f,new ActivityResult(Activity.RESULT_OK,new Intent().setData(android.net.Uri.fromFile(new File(root,name)))),true);
  try{click(a,"importPack");await(()->monitor.getHits()==1);if(cancel){await(()->(Boolean)field(a,"importing"));tap("Cancel pack import");}ready();}finally{removeMonitor(monitor);}
 }
 @Override public void onCreate(Bundle b){super.onCreate(b);mode=b.getString("mode","import");start();}
 @Override public void onStart(){Bundle b=new Bundle();try{
  root=new File(getTargetContext().getFilesDir(),"broad-tests");root.mkdirs();report.put("mode",mode).put("pid",android.os.Process.myPid());getUiAutomation();a=(MainActivity)startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));ready();
  File files=getTargetContext().getFilesDir(),cat=new File(files,"pack-library/catalog.json");String model=BroadPack.hash(new File(files,"model.gguf"));report.put("saved_model_before",model);check(a.modelReady(),"Saved model not loaded");click(field(a,"nativePanel"),"unload");ready();
  if(mode.equals("import")){
   PackLibrary.Snapshot old=(PackLibrary.Snapshot)field(a,"catalog");check(old.entries.size()==2||old.entries.size()==3,"Expected pinned fixture editions");long t=System.nanoTime();
   if(old.entries.size()==2){importPack("broad-reference.plpack",false);report.put("import_ms",(System.nanoTime()-t)/1e6);}else report.put("existing_broad_reused",true);
   PackLibrary.Snapshot next=(PackLibrary.Snapshot)field(a,"catalog");check(next.entries.size()==3&&next.engine.size()==26870,"Broad import did not retain small editions: "+((TextView)field(a,"packStatus")).getText());byte[] saved=Files.readAllBytes(cat.toPath());
   t=System.nanoTime();importPack("corrupt.plpack",false);check(Arrays.equals(saved,Files.readAllBytes(cat.toPath())),"Corrupt import changed catalog");check(((TextView)field(a,"packStatus")).getText().toString().contains("rejected"),"Corrupt import not rejected");File isolated=new File(root,"corrupt-check-"+android.os.Process.myPid());isolated.mkdirs();String failure="";try{File bad=new File(root,"corrupt.plpack");BroadPack.prepare(bad,isolated,BroadPack.hash(bad),()->false);}catch(Exception e){failure=e.toString();}check(failure.contains("Index SHA-256 mismatch"),"Corrupt index not rejected by byte validation: "+failure);check(isolated.listFiles().length==0,"Corrupt stages retained");report.put("corrupt_index_failure",failure);
   report.put("corrupt_status",((TextView)field(a,"packStatus")).getText().toString()).put("corrupt_ms",(System.nanoTime()-t)/1e6);
   t=System.nanoTime();importPack("broad-reference.plpack",true);check(Arrays.equals(saved,Files.readAllBytes(cat.toPath())),"Cancellation changed catalog");check(((TextView)field(a,"packStatus")).getText().toString().contains("rejected"),"Cancellation not rejected");report.put("cancel_ms",(System.nanoTime()-t)/1e6).put("cancel_status",((TextView)field(a,"packStatus")).getText().toString());
  }
  System.gc();Thread.sleep(100);JSONObject before=memory();long open=System.nanoTime();PackLibrary.Snapshot snapshot=new PackLibrary(files).load();report.put("open_ms",(System.nanoTime()-open)/1e6);System.gc();Thread.sleep(100);JSONObject after=memory();report.put("before_open",before).put("after_open",after);check(after.getLong("java_used")-before.getLong("java_used")<32L*1024*1024,"Opening allocated unbounded corpus heap");
  check(snapshot.entries.size()==3&&snapshot.engine.size()==26870&&snapshot.distinctDocuments==1094,"Restart/count/small-pack compatibility");report.put("collections",3).put("documents",snapshot.distinctDocuments).put("passages",snapshot.engine.size());
  JSONObject protocol=new JSONObject(new String(Files.readAllBytes(new File(root,"protocol.json").toPath()),StandardCharsets.UTF_8));JSONArray cases=new JSONArray();
  for(int i=0;i<protocol.getJSONArray("queries").length();i++){
   JSONObject q=protocol.getJSONArray("queries").getJSONObject(i);long t=System.nanoTime();ResearchEngine.Result result=snapshot.engine.research(q.getString("question"));JSONArray hits=new JSONArray();for(ResearchEngine.Hit h:result.hits)hits.put(new JSONObject().put("id",h.passage.id).put("title",h.passage.title).put("text",h.passage.text).put("provenance",h.passage.collectionProvenance).put("rights",h.passage.license).put("url",h.passage.url).put("date",h.passage.sourceDate));cases.put(new JSONObject().put("id",q.getString("id")).put("question",q.getString("question")).put("ms",(System.nanoTime()-t)/1e6).put("candidates",result.candidatesScored).put("controller_route",AnswerEngine.answer(q.getString("question"),result,null,x->{},()->false).kind.name()).put("hits",hits));
  }report.put("queries",cases);System.gc();Thread.sleep(100);report.put("after_queries",memory());
  // Actual Activity source controls for each area; model is unloaded, not a generation test.
  for(String question:new String[]{"Algae","Ancient Egypt","Algeria","Absolute value","ASCII","Constitution","Cooking","Airline"}){
   runOnMainSync(()->((EditText)field(a,"question")).setText(question));click(a,"search");ready();ResearchEngine.Result r=(ResearchEngine.Result)field(a,"latestEvidence");int selected=-1;for(int i=0;i<r.hits.size();i++)if(r.hits.get(i).passage.id.contains("_wiki-")){selected=i;break;}check(selected>=0,"No broad source UI hit: "+question);final int ix=selected;ResearchEngine.Passage p=r.hits.get(ix).passage;runOnMainSync(()->((LinearLayout)field(a,"sourceList")).getChildAt(ix).performClick());await(()->visible(getUiAutomation().getRootInActiveWindow()).contains(p.text));String v=visible(getUiAutomation().getRootInActiveWindow());check(v.contains(p.id)&&v.contains(p.url)&&v.contains("CC BY-SA 4.0")&&v.contains("Contributor history:")&&v.contains("Generation disabled:"),"Source provenance missing");dialogs.put(new JSONObject().put("question",question).put("citation",p.id).put("visible",v).put("route",a.latestAnswer().kind.name()));
   if(question.equals("ASCII")){capture(mode+"-source");tap("License");await(()->visible(getUiAutomation().getRootInActiveWindow()).contains("Creative Commons"));report.put("offline_license_visible",true).put("license_visible_text",visible(getUiAutomation().getRootInActiveWindow()));Thread.sleep(600);capture(mode+"-license");tap("Close");}else tap("Close");
  }
  report.put("dialogs",dialogs).put("saved_model_after",BroadPack.hash(new File(files,"model.gguf")));check(model.equals(report.getString("saved_model_after")),"Saved model changed");
  File[] stages=new File(files,"pack-library").listFiles((d,n)->n.endsWith(".partial"));check(stages.length==0,"Stages survived failure/cancel");report.put("stages",stages.length).put("status","PASS");
 }catch(Throwable e){try{report.put("status","FAIL").put("failure",e.toString());}catch(Exception ignored){}b.putString("failure",e.toString());}
 finally{try{if(a!=null){ready();runOnMainSync(a::finish);}Files.write(new File(root,mode+".json").toPath(),report.toString(2).getBytes(StandardCharsets.UTF_8));}catch(Throwable e){try{report.put("status","FAIL");}catch(Exception ignored){}b.putString("cleanup_failure",e.toString());}}
 finish(report.optString("status").equals("PASS")?-1:1,b);
 }
}
